contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint depAmount, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depAmount)); require(depAmount <= 1000000000000000000000000000000);
        require(other != address(0) && other != address(this));
        require(depAmount > 0);

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Deposit{value: depAmount}(); if (__ESBMC_reverted()) return;

        uint balOtherBefore = c.balances(other); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balOtherAfter = c.balances(other); if (__ESBMC_reverted()) return;

        assert(reverted || balOtherAfter == balOtherBefore);
    }

    receive() external payable {}
}

