pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(address other, uint256 depAmount, uint256 am) internal {
        depAmount = bound(depAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(other != address(0) && other != address(this));
        vm.assume(depAmount > 0);
        try c.SetMinSum(0) {} catch { return; }
        try c.Deposit{value: depAmount}() {} catch { return; }
        uint256 balOtherBefore;
        try c.balances(other) returns (uint256 __r) { balOtherBefore = __r; } catch { return; }
        bool reverted;
        try c.Collect(am) { reverted = false; } catch { reverted = true; }
        uint256 balOtherAfter;
        try c.balances(other) returns (uint256 __r) { balOtherAfter = __r; } catch { return; }
        assertTrue(reverted || balOtherAfter == balOtherBefore);
    }

    function testFuzz_run(address other, uint256 depAmount, uint256 am) public {
